@module keyQueue  src=keyQueue.lua  loc=94  mode=chunk  self=keyQueue
@deps ctx

# Invariants & contracts
  @invariant  one keyQueue per coordinator; each fill replaces the last frame's entries  @ 4
  @contract  take/takeAny remove what they return, so a claimed press is gone for every later reader  @ 6
  @contract  restore puts a taken entry back at the head, for a declining claimant to hand off  @ 7
  @contract  an owner named at the fill holds the frame; take/takeAny answer nil to others  @ 8
  @contract  held/mods read ImGui live, and answer the same whoever owns the queue  @ 9
  @contract  frameMods is the mask the fill stamped; a reader judges a chord by it, then takes at it  @ 10

# Shapes
  @shape  entry = { key: imguiKey, mods: modMask, repeated: bool }  @ 5

# Imports
  @require ImGui = 'imgui'  @ 12
  @require util = 'util'  @ 13

# Private state
  @state OWNERS = { help = true, modal = true, picker = true, statusEdit = ...  @ 18
  @state KEYS = {}  @ 22
  @state entries, owner, frameMask = {}, nil, 0  @ 40
  @state keyQueue = {}  @ 55

# Private functions
  @fn checked(name)  @ 44-49
      -- A name is one of the four owners or nobody; anything else is a typo, which would
      -- otherwise read as a key that quietly does nothing.
  @fn claimable(claimant)  @ 51-53

# Public API (keyQueue:*)
  @api keyQueue:fill(ownerNow)  @ 59-71
  @api keyQueue:take(key, mods, claimant)  @ 73-80
  @api keyQueue:takeAny(claimant)  @ 82-85
  @api keyQueue:restore(entry)  @ 88
      -- A reader claiming before it acts hands the press back this way when it decides not to.
  @api keyQueue:held(key)  @ 90
  @api keyQueue:mods()  @ 91
  @api keyQueue:frameMods()  @ 92

# Uses (outbound edges)
  @use call    ImGui.GetKeyMods  @ fill:61 mods:91
  @use call    ImGui.IsKeyDown  @ held:90
  @use call    ImGui.IsKeyPressed  @ fill:65,68
  @use call    util.add  @ <load>:34 fill:66
  @use require imgui  @ <load>:12
  @use require util  @ <load>:13

# Calls (intra-file)
  @call checked  @ claimable:52 fill:60
  @call claimable  @ take:74 takeAny:83

# Unresolved receivers
  @drop name:sub  @ <load>:32

# Fields (r read / w write incl. constructor keys)
  @field r Mod_None  @ take:75
  @field r ctx  @ 15
  @field w help  @ 18
  @field r key  @ take:77
  @field w key  @ fill:66
  @field w modal  @ 18
  @field r mods  @ take:77
  @field w mods  @ fill:67
  @field w picker  @ 18
  @field w repeated  @ fill:68
  @field w statusEdit  @ 18
